import React, { useState, useRef, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { 
  MessageCircle, X, Paperclip, Smile, Mic, 
  Send, Clock, Check, CheckCheck,
  User, AlertCircle
} from 'lucide-react';
import { io } from 'socket.io-client';

const ChatModal = ({ currentUser, isAuthenticated, onClose }) => {
  const navigate = useNavigate();
  const [messages, setMessages] = useState([]);
  const [inputMessage, setInputMessage] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [conversation, setConversation] = useState(null);
  const [adminInfo, setAdminInfo] = useState(null);
  const [socket, setSocket] = useState(null);
  const [error, setError] = useState(null);
  const messagesEndRef = useRef(null);
  const chatInputRef = useRef(null);

  const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';
  const SOCKET_URL = process.env.REACT_APP_SOCKET_URL || 'http://localhost:5000';

  const getAuthToken = () => localStorage.getItem('authToken');

  // Rediriger si pas connecté
  useEffect(() => {
    if (!isAuthenticated || !currentUser) {
      setError('Vous devez être connecté pour utiliser le chat');
      setIsLoading(false);
    }
  }, [isAuthenticated, currentUser]);

  // Initialiser Socket.io
  useEffect(() => {
    if (!isAuthenticated || !currentUser || !getAuthToken()) return;

    const newSocket = io(SOCKET_URL, {
      query: { userId: currentUser.id, token: getAuthToken() },
      transports: ['websocket', 'polling'],
    });

    newSocket.on('connect', () => console.log('✅ Connecté au chat'));
    newSocket.on('connect_error', (err) => setError('Connexion au chat temporairement indisponible'));
    newSocket.on('receiveMessage', (msg) => setMessages(prev => [...prev, msg]));
    newSocket.on('userTyping', (data) => {
      if (data.conversationId === conversation?.id && data.userId !== currentUser.id) {
        setIsTyping(true);
        setTimeout(() => setIsTyping(false), 3000);
      }
    });
    newSocket.on('messageRead', (data) => {
      setMessages(prev => prev.map(m => data.messageIds.includes(m.id) ? { ...m, is_read: true } : m));
    });

    setSocket(newSocket);
    return () => newSocket.disconnect();
  }, [isAuthenticated, currentUser, conversation]);

  // Charger ou créer une conversation
  useEffect(() => {
    if (!isAuthenticated || !currentUser || !getAuthToken()) return;
    loadOrCreateConversation();
  }, [isAuthenticated, currentUser]);

  const loadOrCreateConversation = async () => {
    try {
      setIsLoading(true);
      setError(null);
      const token = getAuthToken();
      if (!token) { navigate('/login'); return; }

      const config = { headers: { 'Authorization': `Bearer ${token}` } };
      const convRes = await axios.get(`${API_URL}/messages/conversations`, config);

      let convData = convRes.data.conversations?.find(c => c.status === 'open') || null;

      if (!convData) {
        // Créer conversation avec un admin
        const adminsRes = await axios.get(`${API_URL}/users/admins`, config);
        const adminId = adminsRes.data.admins[0]?.id || 1;
        const newConvRes = await axios.post(`${API_URL}/messages/conversations/create`, { admin_id: adminId }, config);
        convData = newConvRes.data.conversation;
      }

      setConversation(convData);

      // Charger messages
      const msgRes = await axios.get(`${API_URL}/messages/conversations/${convData.id}/messages`, config);
      setMessages(msgRes.data.messages || []);

      // Charger info admin
      if (convData.admin_id) {
        const adminRes = await axios.get(`${API_URL}/users/${convData.admin_id}`, config);
        setAdminInfo(adminRes.data.user);
      }

    } catch (err) {
      console.error(err);
      setError('Impossible de charger le chat.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleSendMessage = async () => {
    if (!inputMessage.trim() || !conversation) return;
    const tempId = Date.now();
    const tempMessage = { 
      id: tempId,
      content: inputMessage.trim(),
      sender_id: currentUser.id,
      conversation_id: conversation.id,
      created_at: new Date().toISOString(),
      is_read: false,
      sender: { first_name: currentUser.first_name, last_name: currentUser.last_name }
    };

    setMessages(prev => [...prev, tempMessage]);
    setInputMessage('');
    scrollToBottom();

    try {
      const token = getAuthToken();
      const res = await axios.post(`${API_URL}/messages/conversations/${conversation.id}/messages`,
        { content: tempMessage.content },
        { headers: { 'Authorization': `Bearer ${token}` } }
      );
      const newMessage = res.data.message;
      setMessages(prev => prev.map(m => m.id === tempId ? { ...newMessage, sender: tempMessage.sender } : m));
      if (socket?.connected) socket.emit('sendMessage', { conversationId: conversation.id, message: newMessage });
    } catch {
      setMessages(prev => prev.map(m => m.id === tempId ? { ...m, error: true } : m));
    }
  };

  const handleTyping = () => {
    if (socket?.connected && conversation) socket.emit('typing', { conversationId: conversation.id, userId: currentUser.id });
  };

  const handleKeyPress = (e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSendMessage(); } };
  const scrollToBottom = () => setTimeout(() => messagesEndRef.current?.scrollIntoView({ behavior: "smooth" }), 100);
  useEffect(() => scrollToBottom(), [messages]);

  const formatTime = (dateString) => new Date(dateString).toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' });

  if (!isAuthenticated || !currentUser) {
    return (
      <div className="fixed bottom-6 right-6 w-80 sm:w-96 bg-white dark:bg-neutral-900 rounded-2xl shadow-2xl border dark:border-neutral-800 z-50 animate-slide-up">
        <div className="p-4 text-center">Veuillez vous connecter pour accéder au chat.</div>
        <button onClick={() => navigate('/login')} className="m-3 p-2 bg-primary-500 text-white rounded">Se connecter</button>
      </div>
    );
  }

  return (
    <div className="fixed bottom-6 right-6 w-80 sm:w-96 bg-white dark:bg-neutral-900 rounded-2xl shadow-2xl border dark:border-neutral-800 z-50 animate-slide-up">
      {/* Header */}
      <div className="p-4 bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-t-2xl flex justify-between items-center">
        <div className="flex items-center space-x-3">
          {adminInfo?.avatar ? <img src={adminInfo.avatar} className="h-10 w-10 rounded-full" alt="Admin"/> : <User className="h-10 w-10"/>}
          <div>
            <h3 className="font-bold">{adminInfo ? `${adminInfo.first_name} ${adminInfo.last_name}` : 'Support Nexus'}</h3>
            <p className="text-xs">{adminInfo?.role === 'admin' ? 'Conseiller • En ligne' : 'En attente'}</p>
          </div>
        </div>
        <button onClick={onClose}><X /></button>
      </div>

      {/* Messages */}
      <div className="h-64 sm:h-72 p-4 overflow-y-auto bg-gray-50 dark:bg-neutral-950">
        {error ? (
          <div className="flex flex-col items-center justify-center h-full space-y-3">
            <AlertCircle className="h-12 w-12 text-red-500" />
            <p className="text-red-600">{error}</p>
            <button onClick={loadOrCreateConversation} className="px-4 py-2 bg-primary-500 text-white rounded">Réessayer</button>
          </div>
        ) : messages.length === 0 ? (
          <p className="text-center text-gray-600">Aucun message. Commencez la conversation !</p>
        ) : (
          messages.map(msg => (
            <div key={msg.id} className={`flex ${msg.sender_id === currentUser.id ? 'justify-end' : 'justify-start'} mb-2`}>
              <div className={`p-3 rounded-2xl max-w-[85%] ${msg.sender_id === currentUser.id ? 'bg-primary-500 text-white rounded-br-none' : 'bg-white dark:bg-neutral-800 text-gray-900 rounded-bl-none border dark:border-neutral-700'}`}>
                {msg.sender_id !== currentUser.id && <span className="text-xs font-medium">{msg.sender?.first_name}</span>}
                <p className="text-sm">{msg.content}</p>
                <div className="text-xs mt-1 flex justify-between">
                  <span>{formatTime(msg.created_at)}</span>
                  {msg.sender_id === currentUser.id && (msg.is_read ? <CheckCheck className="h-3 w-3 text-blue-300"/> : <Check className="h-3 w-3 opacity-70"/>)}
                </div>
              </div>
            </div>
          ))
        )}
        {isTyping && <p className="text-xs text-gray-500 italic">{adminInfo?.first_name || 'Support'} est en train d\'écrire...</p>}
        <div ref={messagesEndRef} />
      </div>

      {/* Input */}
      <div className="p-3 border-t dark:border-neutral-800 bg-white dark:bg-neutral-900 rounded-b-2xl flex space-x-2">
        <input
          ref={chatInputRef}
          type="text"
          value={inputMessage}
          onChange={e => { setInputMessage(e.target.value); handleTyping(); }}
          onKeyPress={handleKeyPress}
          placeholder="Écrivez votre message..."
          className="flex-1 rounded-xl border dark:border-neutral-700 p-2"
        />
        <button onClick={handleSendMessage} className="p-2 bg-primary-500 text-white rounded-xl"><Send /></button>
      </div>
    </div>
  );
};

export default ChatModal;
